import sys


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    m = int(data[1])
    parent = list(range(n + 1))
    owes = [0] * (n + 1)
    owed = [0] * (n + 1)

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    pos = 2
    for _ in range(m):
        u = int(data[pos])
        v = int(data[pos + 1])
        pos += 2
        owes[u] += 1
        owed[v] += 1
        ru = find(u)
        rv = find(v)
        if ru != rv:
            parent[ru] = rv
    extra = 0
    groups = {}
    for v in range(1, n + 1):
        if owes[v] or owed[v]:
            if owes[v] > owed[v]:
                extra += owes[v] - owed[v]
            root = find(v)
            if owes[v] != owed[v]:
                groups[root] = False
            elif root not in groups:
                groups[root] = True
    settled = 0
    for ok in groups.values():
        if ok:
            settled += 1
    sys.stdout.write(str(extra) + " " + str(settled + (1 if extra else 0)) + "\n")


main()
